PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS Settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, passwordHash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Sessions (tokenHash TEXT PRIMARY KEY, userId TEXT REFERENCES Users(id) ON DELETE CASCADE, csrfToken TEXT NOT NULL, expiresAt INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON Sessions(expiresAt);
CREATE TABLE IF NOT EXISTS QuoteRequests (id TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'new', data TEXT NOT NULL, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ContactMessages (id TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'new', data TEXT NOT NULL, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ProjectImages (id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES Projects(id) ON DELETE CASCADE, image TEXT NOT NULL, alt TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS Services (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS services_visible ON Services(enabled,position);
CREATE TABLE IF NOT EXISTS Projects (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS projects_visible ON Projects(enabled,position);
CREATE TABLE IF NOT EXISTS SliderImages (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sliderimages_visible ON SliderImages(enabled,position);
CREATE TABLE IF NOT EXISTS BeforeAfter (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS beforeafter_visible ON BeforeAfter(enabled,position);
CREATE TABLE IF NOT EXISTS Testimonials (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS testimonials_visible ON Testimonials(enabled,position);
CREATE TABLE IF NOT EXISTS BlogPosts (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS blogposts_visible ON BlogPosts(enabled,position);
CREATE TABLE IF NOT EXISTS Areas (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS areas_visible ON Areas(enabled,position);
CREATE TABLE IF NOT EXISTS Categories (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS categories_visible ON Categories(enabled,position);
CREATE TABLE IF NOT EXISTS SEOSettings (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS seosettings_visible ON SEOSettings(enabled,position);
CREATE TABLE IF NOT EXISTS Offers (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS offers_visible ON Offers(enabled,position);

CREATE TABLE IF NOT EXISTS AdminSetupTokens (tokenHash TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL);
